+import { useEffect, useRef, useState } from 'react';

 type State = 'loading' | 'success' | 'error';

 export function AsyncPanel() {
   const [state, setState] = useState<State>('loading');
+  const [attempt, setAttempt] = useState(0);
+  const retryingRef = useRef(false);

   useEffect(() => {
+    let cancelled = false;
     const timer = window.setTimeout(() => {
+      if (cancelled) return;
+      retryingRef.current = false;
       const requested = new URLSearchParams(window.location.search).get('sync');
-      setState(requested === 'error' ? 'error' : 'success');
+      const failed = attempt === 0 && requested === 'error';
+      setState(failed ? 'error' : 'success');
     }, 120);
-    return () => window.clearTimeout(timer);
-  }, []);
+    return () => {
+      cancelled = true;
+      window.clearTimeout(timer);
+    };
+  }, [attempt]);
+
+  const retry = () => {
+    if (retryingRef.current) return;
+    retryingRef.current = true;
+    setState('loading');
+    setAttempt((current) => current + 1);
+  };

   return (
     <section className="card sync-card" aria-live="polite">
@@ -22,9 +38,11 @@ export function AsyncPanel() {
         <div className="sync-state error" role="alert">
